public class PasswordChecker {public static String strength(String pw){int n=0;if(pw.length()>=8)n++;if(pw.matches(".*[A-Z].*"))n++;if(pw.matches(".*[0-9].*"))n++;if(pw.matches(".*[^a-zA-Z0-9].*"))n++;return n<=1?"Weak":n<=3?"Medium":"Strong";}public static void main(String[] args){for(String p:new String[]{"abc","abcdef12","Abcd1234!"}){System.out.println("Password: "+p);System.out.println("Length >= 8: "+(p.length()>=8));System.out.println("Uppercase: "+p.matches(".*[A-Z].*"));System.out.println("Digit: "+p.matches(".*[0-9].*"));System.out.println("Special character: "+p.matches(".*[^a-zA-Z0-9].*"));System.out.println("Strength: "+strength(p));}}}
